style.css:
@-moz-document domain("www.google.com") {
body {
  display: flex;
  flex-direction: column;
  align-items: center;
}

body .main {
  width: max-content;
}

#searchform {
  display: flex;
  justify-content: center;
}

#searchform > div:nth-child(2) {
  width: min(60%, 652px);
}

#searchform form + div {
  position: fixed;
  right: 0;
}

#rcnt > div {
  display: flex;
  justify-content: center;
  grid-column: 0;
}
}
